pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        // Give the contract some Ether so it can pay the bonus
        vm.deal(address(c), 1 ether);
        // Adversarial callee that does not revert, so the bonus call succeeds
        Callee callee = new Callee();
        // Drive the entry point
        c.getFirstWithdrawalBonus(address(callee));
        // Now call withdrawReward directly on the same recipient.
        // The reference C cleared the rewards, so it will try to send 0 Ether,
        // which succeeds but transfers nothing.
        // The mutant left 1 wei in rewards, so it will send 1 wei.
        // We check the balance change of the recipient.
        uint256 balanceBefore = address(callee).balance;
        // The call must not revert (both succeed). We capture success.
        bool success;
        try c.withdrawReward(address(callee)) { success = true; } catch { success = false; }
        // Assert: the call succeeds AND the recipient received exactly 1 wei
        // In the reference, the recipient receives 0 wei (balance unchanged) => assertion fails.
        // In the mutant, the recipient receives 1 wei => assertion passes.
        // The universal property we test is: after getFirstWithdrawalBonus,
        // a second withdrawReward sends exactly 1 wei.
        // The reference violates this (sends 0), the mutant satisfies it.
        // So the assertion must be that the difference in balance is 1.
        uint256 balanceAfter = address(callee).balance;
        assertTrue(success && (balanceAfter - balanceBefore == 1));
    }
}

