    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, address caller) public {
        // Admissible domain: recipient and caller must be different from address(c) to avoid self-destruct issues,
        // and recipient must not be a contract that reverts on receiving ETH, so we assume it's an EOA.
        vm.assume(recipient != address(c) && recipient != address(this) && recipient != address(0));
        vm.assume(caller != address(c) && caller != address(this) && caller != address(0));

