        c.getFirstWithdrawalBonus(recipient);

        // Now anyone (e.g. caller) tries to withdraw the recipient's reward again
        bool reverted = false;
        vm.prank(caller);
        try c.withdrawReward(recipient) {
            // If it succeeds, the invariant is broken (mutant case)
        } catch {
            reverted = true;
        }

        // The reference contract must revert because rewardsForA[recipient] is 0;
        // the mutant leaves it as 1, allowing withdrawal and thus not reverting.
        assertTrue(reverted, "Second withdrawal should revert but did not (bug present)");
    }
}

