pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address recipient, uint256 initialBalance) public {
        // Bound to keep in admissible domain: recipient must be address(this) to observe balances
        // but the fuzzer can give any address, we'll use a controlled recipient for measurement
        vm.assume(recipient != address(0) && recipient != address(c));
        // Deploy a minimal helper that records received ether
        BonusReceiver receiver = new BonusReceiver();
        address actualRecipient = address(receiver);

        // Fund the contract so it can pay the bonus
        vm.deal(address(c), 1000 ether);

        // Record initial balances
        uint256 contractBalanceBefore = address(c).balance;
        uint256 receiverBalanceBefore = actualRecipient.balance;

        // Call getFirstWithdrawalBonus
        c.getFirstWithdrawalBonus(actualRecipient);

        // Record final balances
        uint256 contractBalanceAfter = address(c).balance;
        uint256 receiverBalanceAfter = actualRecipient.balance;

        // The contract's balance should have decreased by exactly the bonus received
        uint256 contractDecrease = contractBalanceBefore - contractBalanceAfter;
        uint256 receiverIncrease = receiverBalanceAfter - receiverBalanceBefore;

        // General rule: the amount the contract paid out equals the amount the recipient gained,
        // and that amount is exactly the intended bonus of 100.
        // Bug version pays 101, so contractDecrease != receiverIncrease or != 100.
        assertTrue(contractDecrease == receiverIncrease && contractDecrease == 100);
    }
}

