pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 seed) public {
        // Bound seed to a reasonable number of operations (1..5) and generate a sequence of operations
        vm.assume(recipient != address(0) && recipient != address(c));
        uint256 ops = (seed % 5) + 1;
        // Track total rewards ever added to rewardsForA for all recipients
        uint256 totalCredited;
        // We just call getFirstWithdrawalBonus multiple times with different recipient aliases?
        // But the property is about rewardsForA mapping. We can read it only via public getter.
        // Since the contract has NO public getter for rewardsForA, we can't observe it directly.
        // Instead, we measure address(c).balance before and after a fixed withdrawal to detect the bug.
        // The bug leaves rewardsForA[recipient] > 0 after withdrawal, so a second withdrawal will drain extra balance.
        // We'll use a helper that does NOT revert on receive to ensure success.
        // Deploy a non-reverting receiver to avoid revert interference.
        NonRevertingReceiver receiver = new NonRevertingReceiver();
        address payable payee = payable(address(receiver));

        // Give the contract enough ether to pay out rewards
        vm.deal(address(c), 1000 ether);

        // Fund the recipient under test
        vm.prank(address(c)); // not really needed
        // We need to set up rewardsForA for the payee. We use getFirstWithdrawalBonus to do that.
        // getFirstWithdrawalBonus will call withdrawReward immediately, which will reset properly in ref, but bug leaves residual.
        // After the first call, we check if rewardsForA[payee] is zero (via second withdrawal behavior).
        // But getFirstWithdrawalBonus cannot be called twice for same recipient because of claimedBonus.
        // So we'll just call withdrawReward directly after manually setting rewardsForA.
        // But we have no setter. The only way to set rewardsForA is through getFirstWithdrawalBonus.
        // However, getFirstWithdrawalBonus sets claimedBonus[payee] = true, blocking further getFirstWithdrawalBonus.
        // To test withdrawReward independently, we need rewardsForA to be nonzero for a fresh address.
        // So we use getFirstWithdrawalBonus on a fresh address, which transfers out and possibly resets.
        // After that, rewardsForA should be zero in reference, but nonzero in bug.

        // We'll measure balance of contract before and after a second call to withdrawReward on the same address.
        // But withdrawReward on an address with zero rewards transfers nothing and costs nothing, so balance unchanged.
        // If bug leaves nonzero, second withdrawal will transfer extra ether.

        // Step 1: Call getFirstWithdrawalBonus for a fresh address
        c.getFirstWithdrawalBonus(payee);

        // Step 2: Record balance after that
        uint256 balanceAfterFirst = address(c).balance;

        // Step 3: Wait until we can call withdrawReward again. getFirstWithdrawalBonus already called withdrawReward once.
        // We can directly call withdrawReward on the same payee. In reference, rewardsForA is zero, so 0 transfer, balance unchanged.
        // In bug, rewardsForA is 100, so 100 ether will be transferred again, reducing balance by 100.
        c.withdrawReward(payee);

        uint256 balanceAfterSecond = address(c).balance;

        // Assert: In the reference, balanceAfterSecond == balanceAfterFirst (no extra drain).
        // In the bug, balanceAfterSecond < balanceAfterFirst (extra drain).
        assertEq(balanceAfterSecond, balanceAfterFirst, "Balance must not change on second withdraw if already reset");
    }
}

